#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <stdlib.h>
#include <stdio.h>
#include <errno.h>
#include <limits.h>
#include <string>
#include <vector>
#include <mutex>
#include <filesystem>

namespace fs = std::filesystem;

class SecureUploadHandler {
private:
    std::string upload_root_;
    std::string staging_dir_;
    int root_fd_;  // File descriptor for upload root directory
    std::mutex upload_mutex_;

    // Validate filename contains no path traversal
    bool validate_filename(const std::string& name) {
        if (name.empty() || name.length() > 255) return false;
        if (name[0] == '.') return false;
        if (name.find('/') != std::string::npos) return false;
        if (name.find('\\') != std::string::npos) return false;
        if (name.find('\0') != std::string::npos) return false;
        for (char c : name) {
            unsigned char uc = static_cast<unsigned char>(c);
            if (!isalnum(uc) && c != '-' && c != '_' && c != '.') return false;
        }
        return true;
    }

    // Write data to staging area
    // TODO: review - should we add explicit symlink check here too?
    std::string write_to_staging(const std::string& filename, 
                                  const std::vector<uint8_t>& data) {
        std::string staging_path = staging_dir_ + "/tmp_" + filename;

        int fd = open(staging_path.c_str(), 
                      O_WRONLY | O_CREAT | O_TRUNC | O_NOFOLLOW,
                      0644);
        if (fd < 0) return "";

        size_t written = 0;
        while (written < data.size()) {
            ssize_t ret = write(fd, data.data() + written, 
                               data.size() - written);
            if (ret < 0) {
                close(fd);
                unlink(staging_path.c_str());
                return "";
            }
            written += ret;
        }

        fsync(fd);
        close(fd);
        return staging_path;
    }

public:
    SecureUploadHandler(const std::string& root, const std::string& staging)
        : upload_root_(root), staging_dir_(staging), root_fd_(-1) {
        mkdir(upload_root_.c_str(), 0755);
        mkdir(staging_dir_.c_str(), 0700);
        // Open root directory fd for use with *at() operations
        // O_NOFOLLOW on the directory itself prevents root from being a symlink
        root_fd_ = open(upload_root_.c_str(), O_RDONLY | O_DIRECTORY | O_NOFOLLOW);
    }

    ~SecureUploadHandler() {
        if (root_fd_ >= 0) close(root_fd_);
    }

    // Main upload entry point
    // Uses linkat + unlink pattern which is race-free:
    // - We link the staged file into the target directory using the
    //   directory fd (root_fd_), so the target is resolved relative
    //   to the opened directory, not re-traversed via path.
    // - The filename cannot contain '/' so no traversal is possible.
    // - If target already exists as a symlink, linkat will fail or
    //   follow based on flags - we do NOT pass AT_SYMLINK_FOLLOW
    //   so existing symlinks at the target cause EEXIST, not traversal.
    int handle_upload(const std::string& user_filename,
                      const std::vector<uint8_t>& file_data,
                      uid_t requesting_uid) {
        // Step 1: Validate filename format
        if (!validate_filename(user_filename)) {
            return -1;
        }

        // Step 2: Size limit (10MB)
        if (file_data.size() > 10 * 1024 * 1024) {
            return -2;
        }

        // Step 3: Verify root_fd_ is valid
        if (root_fd_ < 0) {
            return -3;
        }

        // Step 4: Write to staging area
        std::string staged = write_to_staging(user_filename, file_data);
        if (staged.empty()) {
            return -4;
        }

        // Step 5: First, try to unlink any existing file at target
        // unlinkat with root_fd_ + validated filename (no slash) is safe
        unlinkat(root_fd_, user_filename.c_str(), 0);  // ignore error (ENOENT is fine)

        // Step 6: Link staged file into target directory
        // Using AT_EMPTY_PATH on the staged file's fd would be ideal,
        // but we use the path-based linkat which is still safe because:
        // - staged path is in our controlled staging_dir_ (mode 0700)
        // - target is root_fd_ + validated simple filename
        // - No AT_SYMLINK_FOLLOW flag means symlinks at target rejected
        int ret = linkat(AT_FDCWD, staged.c_str(),
                         root_fd_, user_filename.c_str(), 0);

        // Step 7: Clean up staging file regardless of link result
        unlink(staged.c_str());

        if (ret != 0) {
            return -5;
        }

        return 0;
    }
};

int process_upload_request(SecureUploadHandler& handler,
                           const std::string& filename,
                           const std::vector<uint8_t>& body,
                           uid_t uid) {
    return handler.handle_upload(filename, body, uid);
}
